+        let affected = tx.execute(
+            "UPDATE sessions SET title = ?2 WHERE id = ?1 AND parent_id IS NULL",
+            params![session, title],
+        )?;
+        if affected == 0 {
+            return Err(StorageError::SessionNotFound);
+        }
