+            format!(
+                "session title exceeds {MAX_SESSION_TITLE_BYTES} bytes; shorten it or select all to replace"
+            )
+        } else {
+            format!("session title truncated at {MAX_SESSION_TITLE_BYTES} bytes")
+        }
+    }
